   611  int search_trie(name_context *ctx, char *data, size_t len, int n, int *exact, int *is_fixed, int *fixed_len) {
   612      int nlines = 0;
   613      size_t i;
   614      trie_t *t;
   615      int from = -1, p3 = -1;
   616      *exact = 0;
   617      *fixed_len = 0;
   618      *is_fixed = 0;
   619
   620      // Horrid hack for the encoder only.
   621      // We optimise per known name format here.
   622      int prefix_len;
   623      char *d = *data == '@' ? data+1 : data;
   624      int l   = *data == '@' ? len-1  : len;
   625      int f = (*data == '>') ? 1 : 0;
   626      if (l > 70 && d[f+0] == 'm' && d[7] == '_' && d[f+14] == '_' && d[f+61] == '/') {
   627          prefix_len = 60; // PacBio
   628          *is_fixed = 0;
   629      } else if (l == 17 && d[f+5] == ':' && d[f+11] == ':') {
   630          prefix_len = 6;  // IonTorrent
   631          *fixed_len = 6;
   632          *is_fixed = 1;
   633      } else if (l > 37 && d[f+8] == '-' && d[f+13] == '-' && d[f+18] == '-' && d[f+23] == '-' &&
   634                 ((d[f+0] >= '0' && d[f+0] <='9') || (d[f+0] >= 'a' && d[f+0] <= 'f')) &&
   635                 ((d[f+35] >= '0' && d[f+35] <='9') || (d[f+35] >= 'a' && d[f+35] <= 'f'))) {
   636          // ONT: f33d30d5-6eb8-4115-8f46-154c2620a5da_Basecall_1D_template...
   637          prefix_len = 37;
   638          *fixed_len = 37;
   639          *is_fixed = 1;
   640      } else {
   641          // Check Illumina and trim back to lane:tile:x:y.
   642          int colons = 0;
   643          for (i = 0; i < len && data[i] > ' '; i++)
   644              ;
   645          while (i > 0 && colons < 4)
   646              if (data[--i] == ':')
   647                  colons++;
   648
   649          if (colons == 4) {
   650              // Constant illumina prefix
   651              *fixed_len = i+1;
   652              prefix_len = i+1;
   653              *is_fixed = 1;
   654          } else {
   655              // Unknown, don't use a fixed len, but still search
   656              // for any exact matches.
   657              prefix_len = INT_MAX;
   658              *is_fixed = 0;
   659          }
   660      }
   661      //prefix_len = INT_MAX;
   662
   663      if (!ctx->t_head) {
   664          ctx->t_head = calloc(1, sizeof(*ctx->t_head));
   665          if (!ctx->t_head)
   666              return -1;
   667      }
   668
   669      // Find an item in the trie
   670      for (nlines = i = 0; i < len; i++, nlines++) {
   671          t = ctx->t_head;
   672          while (i < len && data[i] > '\n') {
   673              unsigned char c = data[i++];
   674              if (c & 0x80)
   675                  //fprintf(stderr, "8-bit ASCII is unsupported\n");
   676                  abort();
   677              c &= 127;
   678
   679              trie_t *x = t->next;
   680              while (x && x->c != c)
   681                  x = x->sibling;
   682              t = x;
   683
   684  //          t = t->next[c];
   685
   686  //          if (!t)
   687  //              return -1;
   688
   689              from = t->n;
   690              if (i == prefix_len) p3 = t->n;
   691              //if (t->count >= .0035*ctx->t_head->count && t->n != n) p3 = t->n; // pacbio
   692              //if (i == 60) p3 = t->n; // pacbio
   693              //if (i == 7) p3 = t->n; // iontorrent
   694              t->n = n;
   695          }
   696      }
   697
   698      //printf("Looked for %d, found %d, prefix %d\n", n, from, p3);
   699
   700      *exact = (n != from) && len;
   701      return *exact ? from : p3;
   702  }
