   332  static int encode_token_type(name_context *ctx, int ntok,
   333                               enum name_type type) {
   334      int id = ntok<<4;
   335
   336      if (descriptor_grow(&ctx->desc[id], 1) < 0) return -1;
   337
   338      ctx->desc[id].buf[ctx->desc[id].buf_l++] = type;
   339
   340      return 0;
   341  }
