   351  static enum name_type decode_token_type(name_context *ctx, int ntok) {
   352      int id = ntok<<4;
   353      if (ctx->desc[id].buf_l >= ctx->desc[id].buf_a) return -1;
   354      return ctx->desc[id].buf[ctx->desc[id].buf_l++];
   355  }
