   357  // int stored as 32-bit quantities
   358  static int encode_token_int(name_context *ctx, int ntok,
   359                              enum name_type type, uint32_t val) {
   360      int id = (ntok<<4) | type;
   361
   362      if (encode_token_type(ctx, ntok, type) < 0) return -1;
   363      if (descriptor_grow(&ctx->desc[id], 4) < 0) return -1;
   364
   365      uint8_t *cp = &ctx->desc[id].buf[ctx->desc[id].buf_l];
   366      cp[0] = (val >>  0) & 0xff;
   367      cp[1] = (val >>  8) & 0xff;
   368      cp[2] = (val >> 16) & 0xff;
   369      cp[3] = (val >> 24) & 0xff;
   370      ctx->desc[id].buf_l += 4;
   371
   372      return 0;
   373  }
   374
   375  // Return 0 on success, -1 on failure;
   376  static int decode_token_int(name_context *ctx, int ntok,
   377                              enum name_type type, uint32_t *val) {
   378      int id = (ntok<<4) | type;
   379
   380      if (ctx->desc[id].buf_l + 4 > ctx->desc[id].buf_a)
   381          return -1;
   382
   383      uint8_t *cp = ctx->desc[id].buf + ctx->desc[id].buf_l;
   384      *val = (cp[0]) + (cp[1]<<8) + (cp[2]<<16) + (cp[3]<<24);
   385      ctx->desc[id].buf_l += 4;
   386
   387      return 0;
   388  }
