   427  // Basic C-string style for now.
   428  //
   429  // Maybe XOR with previous string as context?
   430  // This permits partial match to be encoded efficiently.
   431  static int encode_token_alpha(name_context *ctx, int ntok,
   432                                char *str, int len) {
   433      int id = (ntok<<4) | N_ALPHA;
   434
   435      if (encode_token_type(ctx, ntok, N_ALPHA) < 0)  return -1;
   436      if (descriptor_grow(&ctx->desc[id], len+1) < 0) return -1;
   437      memcpy(&ctx->desc[id].buf[ctx->desc[id].buf_l], str, len);
   438      ctx->desc[id].buf[ctx->desc[id].buf_l+len] = 0;
   439      ctx->desc[id].buf_l += len+1;
   440
   441      return 0;
   442  }
   443
   444  // FIXME: need limit on string length for security.
   445  // Return length on success, -1 on failure;
   446  static int decode_token_alpha(name_context *ctx, int ntok, char *str, int max_len) {
   447      int id = (ntok<<4) | N_ALPHA;
   448      char c;
   449      int len = 0;
   450      if (ctx->desc[id].buf_l  >= ctx->desc[id].buf_a)
   451          return -1;
   452      do {
   453          c = ctx->desc[id].buf[ctx->desc[id].buf_l++];
   454          str[len++] = c;
   455      } while(c && len < max_len && ctx->desc[id].buf_l < ctx->desc[id].buf_a);
   456
   457      return len-1;
   458  }
